/**
 * The server-created identity every downstream component receives. Its four fields are the only
 * principal information the rest of the system may rely on:
 *
 * - `tenantId` / `subject` come from a validated token claim (see `authenticator.ts`), never
 *   from a header, a request body, prompt text, or a tool argument.
 * - `authSource` says which mechanism established the identity. In this lab it is always the
 *   local test issuer; a real Teams/Entra integration would add a value here and needs its own
 *   evidence (see README, "Boundary").
 * - `requestId` is generated by the server for this request; a client-supplied request ID is
 *   ignored.
 */
export interface SecurityContext {
  readonly tenantId: string;
  readonly subject: string;
  readonly authSource: "local-test-token";
  readonly requestId: string;
}

/**
 * Objects this module has minted. `assertSecurityContext` accepts only these, so an object
 * literal assembled elsewhere — for example from parsed tool arguments or a request body —
 * cannot pass as a principal even if it has the right shape. Only `authenticator.ts` is meant
 * to call `mintSecurityContext`; tests that need a context go through the authenticator or the
 * explicitly test-named `mintSecurityContextForTest`.
 */
const minted = new WeakSet<object>();

export function mintSecurityContext(fields: SecurityContext): SecurityContext {
  const context = Object.freeze({ ...fields });
  minted.add(context);
  return context;
}

export function mintSecurityContextForTest(fields: Omit<SecurityContext, "authSource">): SecurityContext {
  return mintSecurityContext({ ...fields, authSource: "local-test-token" });
}

export class UntrustedSecurityContextError extends Error {
  public constructor() {
    super("Value is not a server-created SecurityContext.");
    this.name = "UntrustedSecurityContextError";
  }
}

export function assertSecurityContext(value: unknown): asserts value is SecurityContext {
  if (typeof value !== "object" || value === null || !minted.has(value)) {
    throw new UntrustedSecurityContextError();
  }
}
